func isUUIDv7(value string) bool {
	if !govalidator.IsUUID(value) {
		return false
	}

	if len(value) != 36 {
		return false
	}

	if value[14] != '7' {
		return false
	}

	variantChar := value[19]
	if variantChar != '8' && variantChar != '9' && variantChar != 'a' && variantChar != 'b' &&
		variantChar != 'A' && variantChar != 'B' {
		return false
	}

